void UAlsCharacterMovementComponent::PhysWalking(const float DeltaTime, int32 IterationsCount)
{
	RefreshGroundedMovementSettings();

MaintainHorizontalGroundVelocity();
const FVector OldVelocity = Velocity;
Acceleration = FVector::VectorPlaneProject(Acceleration, -GetGravityDirection());

static const auto* EnsureAlwaysEnabledConsoleVariable{
	IConsoleManager::Get().FindConsoleVariable(TEXT("p.LedgeMovement.ApplyDirectMove"))
};
check(EnsureAlwaysEnabledConsoleVariable != nullptr)

// Apply acceleration
const bool bSkipForLedgeMove = bTriedLedgeMove && EnsureAlwaysEnabledConsoleVariable->GetBool();
if( !HasAnimRootMotion() && !CurrentRootMotion.HasOverrideVelocity() && !bSkipForLedgeMove )
{
	CalcVelocity(timeTick, GroundFriction, false, GetMaxBrakingDeceleration());
	// devCode(ensureMsgf(!Velocity.ContainsNaN(), TEXT("PhysWalking: Velocity contains NaN after CalcVelocity (%s)\n%s"), *GetPathNameSafe(this), *Velocity.ToString()));
}

ApplyRootMotionToVelocity(timeTick);
// devCode(ensureMsgf(!Velocity.ContainsNaN(), TEXT("PhysWalking: Velocity contains NaN after Root Motion application (%s)\n%s"), *GetPathNameSafe(this), *Velocity.ToString()));

if (MovementMode != StartingMovementMode || CustomMovementMode != StartingCustomMovementMode)
{
	// Root motion could have taken us out of our current mode
	// No movement has taken place this movement tick so we pass on full time/past iteration count

	MoveAlongFloor(MoveVelocity, timeTick, &StepDownResult);

	if (IsSwimming()) //just entered water
	{
		StartSwimming(OldLocation, OldVelocity, timeTick, remainingTime, Iterations);
		return;
	}
	else if (MovementMode != StartingMovementMode || CustomMovementMode != StartingCustomMovementMode)
	{
		// pawn ended up in a different mode, probably due to the step-up-and-over flow
		// let's refund the estimated unused time (if any) and keep moving in the new mode
		const float DesiredDist = UE_REAL_TO_FLOAT(Delta.Size());
		if (DesiredDist > UE_KINDA_SMALL_NUMBER)
		{
			const float ActualDist = UE_REAL_TO_FLOAT(ProjectToGravityFloor(UpdatedComponent->GetComponentLocation() - OldLocation).Size());
			remainingTime += timeTick * (1.f - FMath::Min(1.f,ActualDist/DesiredDist));
		}
		StartNewPhysics(remainingTime,Iterations);
		return;
	}
}

// Update floor.
// StepUp might have already done it for us.
if (StepDownResult.bComputedFloor)
{
	CurrentFloor = StepDownResult.FloorResult;
}
else
{
	FindFloor(UpdatedComponent->GetComponentLocation(), CurrentFloor, bZeroDelta, NULL);

if (!CurrentFloor.IsWalkableFloor() && !CurrentFloor.HitResult.bStartPenetrating)
{
	const bool bOldMovementBaseValid = OldMovementBaseInterfaceData && OldMovementBaseInterfaceData->IsValid();
	const bool bMustJump = bJustTeleported || bZeroDelta || (!bOldMovementBaseValid || (!CollisionEnabledHasQuery(OldMovementBaseInterfaceData->GetBodyInstanceOwner()->GetCollisionEnabled()) && MovementBaseUtility::IsDynamicBase(OldMovementBaseInterfaceData)));
	if ((bMustJump || !bCheckedFall) && CheckFall(OldFloor, CurrentFloor.HitResult, Delta, OldLocation, remainingTime, timeTick, Iterations, bMustJump) )
	{
		return;

if (ALS_ENSURE(IsValid(GaitSettings.AccelerationAndDecelerationAndGroundFrictionCurve)))
{
	const auto& AccelerationAndDecelerationAndGroundFrictionCurves{
		GaitSettings.AccelerationAndDecelerationAndGroundFrictionCurve->FloatCurves
	};

	MaxAccelerationWalking = AccelerationAndDecelerationAndGroundFrictionCurves[0].Eval(GaitAmount);
	BrakingDecelerationWalking = AccelerationAndDecelerationAndGroundFrictionCurves[1].Eval(GaitAmount);
	GroundFriction = AccelerationAndDecelerationAndGroundFrictionCurves[2].Eval(GaitAmount);
}

pub fn grounded_velocity_step_with_braking_friction(
    velocity: Vec3,
    desired_motion: Vec3,
    max_speed: f32,
    dynamics: GroundedDynamics,
    min_analog_walk_speed: f32,
    braking_friction_factor: f32,
    braking_substep_time: f32,
    delta_seconds: f32,
) -> Vec3 {
    let horizontal_velocity = Vec3::new(velocity.x, 0.0, velocity.z);
    let desired_horizontal = Vec3::new(desired_motion.x, 0.0, desired_motion.z);
    let desired_amount = desired_horizontal.length().min(1.0);
    let speed = horizontal_velocity.length();
    let delta_seconds = delta_seconds.max(0.0);
    if delta_seconds < MIN_MOVEMENT_DELTA_SECONDS { return horizontal_velocity; }
    let acceleration = desired_horizontal.clamp_length_max(1.0) * dynamics.acceleration.max(0.0);
    let has_acceleration = acceleration != Vec3::ZERO;
    let analog_modifier = if has_acceleration && dynamics.acceleration > MAX_ACCELERATION_MIN_FOR_ANALOG_MODIFIER { desired_amount } else { 0.0 };

    velocity,
    params_handle,
    controller,
    mut motor,
    mut cmc_runtime,
    current_base_state,
) in &mut q
{
    let delta_seconds = time.delta_secs() * custom_dilations.get(entity).map_or(1.0, |value| value.0);
    cmc_runtime.grounded_movement_delta = None;
    cmc_runtime.grounded_collision_velocity = None;
    let Ok((roll, mantle)) = actions.get(entity) else {
        continue;
    };
    if !matches!(*locomotion, LocomotionState::Grounded | LocomotionState::Air) {
        continue;
    }
    let root_motion_active = roll.is_some_and(AlsRollState::root_motion_active)
        || mantle.is_some_and(|state| state.active);
    let Some(params) = params_assets.get(params_handle.id()) else {
        continue;
    };
    let world_velocity = Vec3::new(velocity.x, 0.0, velocity.z);
    if *locomotion == LocomotionState::Air {
        if root_motion_active { continue; }
        let inherited = if let Some(mut base) = current_base_state {
            if let Some(previous) = base.entity {
                let (_, support) = support_velocity_from_base(Some(previous),
                    character_contact_point(params, *stance, position.0), &bases, &colliders);
                let inherited = support - base.support_velocity;
                *base = default();
                inherited.with_y(0.0)
            } else { Vec3::ZERO }
        } else { Vec3::ZERO };
        motor.lin.acceleration.x = 0.0;
        motor.lin.acceleration.z = 0.0;
        motor.lin.boost.x = inherited.x;
        motor.lin.boost.z = inherited.z;
        continue;
    }
    let contact_point = character_contact_point(params, *stance, position.0);
    let (base_entity, support_velocity) = support_velocity_from_base(
        controller.basis_memory.standing_on_entity(),
        contact_point,
        &bases,
        &colliders,
    );
    let current = locomotion_velocity(world_velocity, *locomotion,
        current_base_state.as_deref().filter(|_| base_entity.is_some()));
    let max_speed = max_allowed_speed(
        params, *stance, *rotation_mode, max_allowed_gait.0, current, view_yaw.0,
    );
    cmc_runtime.grounded_max_speed = max_speed;
    if root_motion_active { continue; }
    let thresholds = params.gait_speed_thresholds(*stance, *rotation_mode, current, view_yaw.0);
    gait_amount.0 = calculate_gait_amount_for_thresholds(current.length(), thresholds);
    if AlsMovementParams::has_gait_settings(*stance, *rotation_mode) {
        dynamics.0 = params.grounded_dynamics(*stance, *rotation_mode, gait_amount.0);
    }

pub fn air_acceleration_for_horizontal_speed(
    params: &AlsMovementParams,
    horizontal_speed: f32,
) -> f32 {
    let multiplier = if horizontal_speed < AIR_CONTROL_BOOST_SPEED {
        AIR_CONTROL_BOOST_MULTIPLIER
    } else {
        1.0
    };
    params.acceleration.max_acceleration * AIR_CONTROL * multiplier

fn falling_movement_transaction(
    spatial: &SpatialQuery, capsule: &Collider, mut transform: Transform, mut velocity: Vec3,
    desired_motion: Vec3, mut max_speed: f32, params: &AlsMovementParams, gravity: Vec3,
    grounded: (Stance, RotationMode, Gait, f32), landing: (f32, bool, bool),
    terminal: f32, mut remaining: f32, mut iterations: u32, entity: Entity, random_seed: &mut u32,
    candidates: &Query<(Option<&CollisionLayers>, Has<Sensor>, Option<&ColliderOf>, Option<&AlsCollisionLayerOwnership>)>,
    step_permissions: &Query<&AlsMantleTargetPermission>,
    bases: &Query<(&Position, &LinearVelocity, Option<&AngularVelocity>), Without<AlsCharacter>>,
    owners: &Query<&ColliderOf>,
    shapes: &Query<(&Collider, &Position, &Rotation)>,
    transitions: &mut MessageWriter<StateTransitionEvent>,
) -> (Transform, Vec3, u32, bool, LocomotionState, Option<Entity>, f32, Option<LocomotionState>) {
    let mut acceleration = air_acceleration_for_horizontal_speed(params, velocity.with_y(0.0).length())
        .min(params.acceleration.max_acceleration);
    let mut contact = false;
    let mut mode = LocomotionState::Air;
    let mut current_base = None;
    let mut collision_mode = None;
    while remaining >= crate::als::movement_constants::MIN_MOVEMENT_DELTA_SECONDS
        && iterations < params.cmc.max_simulation_iterations {
        iterations += 1;
        let step = crate::als::dynamics::source_movement_time_step(remaining, &params.cmc, iterations);
        let old_velocity = velocity;
        let horizontal = crate::als::dynamics::grounded_velocity_step_with_braking_friction(
            velocity.with_y(0.0), desired_motion, max_speed,
            crate::als::params::GroundedDynamics { acceleration, braking_deceleration: 0.0, ground_friction: 0.0 },
            params.cmc.min_analog_walk_speed, 0.0, params.cmc.braking_substep_time, step);
        velocity = crate::als::dynamics::clamp_falling_velocity(horizontal + Vec3::Y * velocity.y + gravity * step,
            gravity, terminal);

    velocity += crate::als::dynamics::support_velocity_from_base(last_base,
        transform.translation - Vec3::Y * extent.y, bases, owners).1.with_y(0.0);
    current_base = None;
    mode = LocomotionState::Air;
    transitions.write(StateTransitionEvent { entity, dimension: Dimension::LocomotionState,
        from: StateValue::LocomotionState(LocomotionState::Grounded), to: StateValue::LocomotionState(mode) });
    if landing.2 && params.rolling.interrupt_when_in_air {
        mode = LocomotionState::None;
        transitions.write(StateTransitionEvent { entity, dimension: Dimension::LocomotionState,
            from: StateValue::LocomotionState(LocomotionState::Air), to: StateValue::LocomotionState(mode) });
        break;
    }
    acceleration = air_acceleration_for_horizontal_speed(params, velocity.with_y(0.0).length())
        .min(params.acceleration.max_acceleration);
    continue;
}
